// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract IntentManager {
    struct Intent {
        address user;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 minAmountOut;
        bool isFulfilled;
    }

    mapping(uint256 => Intent) public intents;
    uint256 public nextIntentId;

    event IntentCreated(uint256 indexed id, address indexed user, address tokenIn, address tokenOut, uint256 amountIn, uint256 minAmountOut);
    event IntentFulfilled(uint256 indexed id, address indexed agent, uint256 amountOut);

    function createIntent(address tokenIn, address tokenOut, uint256 amountIn, uint256 minAmountOut) external {
        require(amountIn > 0, "Amount must be greater than 0");

        // Transfer the tokens to escrow
        require(IERC20(tokenIn).transferFrom(msg.sender, address(this), amountIn), "Transfer failed");

        intents[nextIntentId] = Intent(msg.sender, tokenIn, tokenOut, amountIn, minAmountOut, false);
        emit IntentCreated(nextIntentId, msg.sender, tokenIn, tokenOut, amountIn, minAmountOut);
        nextIntentId++;
    }

    function fulfillIntent(uint256 id, uint256 amountOut) external {
        Intent storage intent = intents[id];
        require(!intent.isFulfilled, "Intent already fulfilled");
        require(amountOut >= intent.minAmountOut, "Insufficient output amount");

        intent.isFulfilled = true;

        // Agent transfers tokenOut to user
        require(IERC20(intent.tokenOut).transferFrom(msg.sender, intent.user, amountOut), "Agent transfer failed");

        // Contract transfers tokenIn to agent
        require(IERC20(intent.tokenIn).transfer(msg.sender, intent.amountIn), "Escrow release failed");

        emit IntentFulfilled(id, msg.sender, amountOut);
    }
}

src/NexusHub.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract NexusHub {
    struct Agent {
        address owner;
        string name;
        string capabilityURI;
        bool isActive;
    }

    mapping(address => Agent) public agents;
    address[] public agentList;

    event AgentRegistered(address indexed agentAddress, address indexed owner, string name);
    event AgentDeactivated(address indexed agentAddress);

    function registerAgent(address _agentAddress, string memory _name, string memory _capabilityURI) external {
        require(agents[_agentAddress].owner == address(0), "Agent already registered");

        agents[_agentAddress] = Agent({
            owner: msg.sender,
            name: _name,
            capabilityURI: _capabilityURI,
            isActive: true
        });

        agentList.push(_agentAddress);
        emit AgentRegistered(_agentAddress, msg.sender, _name);
    }

    function deactivateAgent(address _agentAddress) external {
        require(agents[_agentAddress].owner == msg.sender, "Only owner can deactivate");
        require(agents[_agentAddress].isActive, "Already inactive");

        agents[_agentAddress].isActive = false;
        emit AgentDeactivated(_agentAddress);
    }

    function getActiveAgents() external view returns (address[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < agentList.length; i++) {
            if (agents[agentList[i]].isActive) {
                count++;
            }
        }

        address[] memory active = new address[](count);
        uint256 index = 0;
        for (uint256 i = 0; i < agentList.length; i++) {
            if (agents[agentList[i]].isActive) {
                active[index] = agentList[i];
                index++;
            }
        }

        return active;
    }
}

src/NexusRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

contract NexusRegistry {
    struct Intent {
        address user;
        string action;
        uint256 amount;
        bool executed;
    }

    mapping(uint256 => Intent) public intents;
    uint256 public intentCount;

    event IntentCreated(uint256 indexed id, address indexed user, string action, uint256 amount);
    event IntentExecuted(uint256 indexed id, address indexed executor);

    function createIntent(string memory action, uint256 amount) external {
        intents[intentCount] = Intent(msg.sender, action, amount, false);
        emit IntentCreated(intentCount, msg.sender, action, amount);
        intentCount++;
    }

    function executeIntent(uint256 id) external {
        require(id < intentCount, "Intent does not exist");
        require(!intents[id].executed, "Intent already executed");

        intents[id].executed = true;
        emit IntentExecuted(id, msg.sender);
    }
}

src/NexusRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract NexusRouter {
    mapping(address => uint256) public agentBalances;
    mapping(address => bool) public registeredAgents;

    event AgentRegistered(address indexed agent);
    event PaymentRouted(address indexed from, address indexed to, uint256 amount, string endpoint);
    event FundsDeposited(address indexed agent, uint256 amount);

    function registerAgent() external {
        require(!registeredAgents[msg.sender], "Already registered");
        registeredAgents[msg.sender] = true;
        emit AgentRegistered(msg.sender);
    }

    function deposit() external payable {
        require(registeredAgents[msg.sender], "Must be registered");
        agentBalances[msg.sender] += msg.value;
        emit FundsDeposited(msg.sender, msg.value);
    }

    function payForInference(address to, uint256 amount, string calldata endpoint) external {
        require(registeredAgents[msg.sender], "Sender not registered");
        require(registeredAgents[to], "Receiver not registered");
        require(agentBalances[msg.sender] >= amount, "Insufficient balance");

        agentBalances[msg.sender] -= amount;
        agentBalances[to] += amount;

        emit PaymentRouted(msg.sender, to, amount, endpoint);
    }
}

